{
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find the two separated 4-row motifs. The encoded upper motif already
    # has a full-width second row; the lower motif's missing continuation is
    # marked by color 1 in the corresponding unoccupied cells of its first row.
    blocks = []
    r = 0
    while r < h:
        if any(grid[r]):
            start = r
            while r < h and any(grid[r]):
                r += 1
            blocks.append((start, r))
        else:
            r += 1
    if len(blocks) >= 2:
        start, end = blocks[1]
        for c in range(w):
            if grid[start][c] == 0 and any(grid[rr][c] for rr in range(start + 1, end)):
                out[start][c] = 1
    return out
