    if blocks:
        start, end = blocks[0]
        # Treat the left-aligned 3x3 glyph as a template and append its
        # continuation over the blank columns to the right.
        for rr in range(start, end):
            if grid[rr][3] != 0 and grid[rr][5] != 0:
                for c in range(6, len(grid[0])):
                    if grid[rr][c] == 0:
                        out[rr][c] = 1
    return out
