{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find vertically separated non-background bands.
    bands = []
    r = 0
    while r < h:
        if any(v != background for v in grid[r]):
            start = r
            while r < h and any(v != background for v in grid[r]):
                r += 1
            bands.append((start, r))
        else:
            r += 1

    out = [row[:] for row in grid]
    if len(bands) < 2:
        return out

    # Paired bands depict the same pattern: one is complete farther to the
    # right, and the other has a truncated right edge. Extend the truncated
    # one from the complete band's matching rows, marking added cells as 1.
    first, second = bands[0], bands[1]
    def rightmost(band):
        return max(c for rr in range(*band) for c, v in enumerate(grid[rr]) if v != background)

    if rightmost(first) >= rightmost(second):
        target, reference = second, first
    else:
        target, reference = first, second

    t0, t1 = target
    s0, s1 = reference
    cutoff = rightmost(target) + 1
    for offset in range(min(t1 - t0, s1 - s0)):
        tr, sr = t0 + offset, s0 + offset
        for c in range(cutoff, w):
            if grid[tr][c] == background and grid[sr][c] != background:
                out[tr][c] = 1
    return out
