{
 "content": "def transform(grid):
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # identify separate patterned row groups
    groups = []
    r = 0
    while r < h:
        if any(v != background for v in grid[r]):
            s = r
            while r < h and any(v != background for v in grid[r]):
                r += 1
            groups.append((s, r))
        else:
            r += 1
    # A pattern is repeated twice. The first occurrence has a shorter extent;
    # its upper rows are completed with the marker color across the empty right side.
    if len(groups) >= 2:
        s, e = groups[0]
        for rr in range(s, e):
            # Rows whose leading 3-column symbol is a 3x3 block/plus are extended.
            if grid[rr][0] != background or grid[rr][1] != background or grid[rr][2] != background:
                continue
            # target code rows are aligned from column 3 and have cells in both edges
            if len(grid[rr]) > 6 and grid[rr][3] != background and grid[rr][5] != background:
                for c in range(6, w):
                    if grid[rr][c] == background:
                        out[rr][c] = 1
    return out
