 "content": "def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous bands of rows containing non-background pattern cells.
    bands = []
    r = 0
    while r < h:
        if any(v != background for v in grid[r]):
            start = r
            while r < h and any(v != background for v in grid[r]):
                r += 1
            bands.append((start, r))
        else:
            r += 1

    # Repeated bands are aligned by row. The more complete band is the source;
    # add color 1 to missing cells after each target row's last existing cell.
    for i, (a, b) in enumerate(bands):
        for c, d in bands[i + 1:]:
            if b - a != d - c:
                continue
            def count(start, end):
                return sum(v != background for rr in range(start, end) for v in grid[rr])
            ca, cb = count(a, b), count(c, d)
            if ca == cb:
                continue
            (ts, te), (ss, se) = ((a, b), (c, d)) if ca < cb else ((c, d), (a, b))
            for offset in range(te - ts):
                tr, sr = ts + offset, ss + offset
                occupied = [j for j, v in enumerate(grid[tr]) if v != background]
                if not occupied:
                    continue
                right = max(occupied)
                for col in range(right + 1, w):
                    if grid[tr][col] == background and grid[sr][col] != background:
                        out[tr][col] = 1
    return out
