            bands.append((s, r))
        else:
            r += 1
    if len(bands) >= 2:
        # The motifs have matching row-wise structure; the incomplete copy is
        # filled to the right of its last existing patterned cell with color 1.
        (a, b), (c, d) = bands[0], bands[1]
        # extend the first band's sparse row whose companion row is solid
        for k in range(min(b-a, d-c)):
            row = a + k
            companion = c + k
            if any(grid[row][x] != background and grid[companion][x] == background for x in range(w)):
