            elif any(grid[companion][x] != background and grid[row][x] == background for x in range(w)):
                target = companion
            else:
                continue
            # only append the missing tail after the coded region
            last = max(x for x,v in enumerate(grid[target]) if v != background)
            for x in range(last + 1, w):
                out[target][x] = 1
    return out
