{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find contiguous patterned bands separated by blank/background rows.
    bands = []
    r = 0
    while r < h:
        if any(v != bg for v in grid[r]):
            start = r
            while r < h and any(v != bg for v in grid[r]):
                r += 1
            bands.append((start, r))
        else:
            r += 1

    # Two repeated bands encode the same figure. Fill whichever band is less
    # complete from the more-complete band, marking the added cells with 1.
    if len(bands) >= 2:
        a, b = bands[0]
        c, d = bands[1]
        if b - a == d - c:
            count_a = sum(v != bg for row in grid[a:b] for v in row)
            count_b = sum(v != bg for row in grid[c:d] for v in row)
            if count_a <= count_b:
                target, source = a, c
            else:
                target, source = c, a
            for k in range(b - a):
                tr, sr = target + k, source + k
                for col in range(w):
                    if grid[tr][col] == bg and grid[sr][col] != bg:
                        out[tr][col] = 1
    return out
