    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The repeated 4-row pattern appears twice. The lower copy shares the
    # first five 3-column tiles with the upper copy, then is truncated; extend
    # it with the upper copy's remaining foreground pattern, marking additions 1.
    bands = []
    r = 0
    while r < h:
        if any(grid[r]):
