        (a, b), (c, d) = bands[:2]
        if b - a == d - c:
            # Their exact common prefix is made of 3-column coded tiles.
            # Find the earliest tile boundary after their aligned prefixes diverge.
            boundary = 0
            for col in range(0, w, 3):
                same = all(grid[a+k][x] == grid[c+k][x]
                           for k in range(b-a) for x in range(col, min(col+3, w)))
